// generated by `cargo xtask protocol` from crates/kiln-protocol, do not edit
import type { GridCellFormat } from "./GridCellFormat";
import type { GridDrawing } from "./GridDrawing";
import type { GridEditor } from "./GridEditor";
import type { GridLayout } from "./GridLayout";
import type { GridMode } from "./GridMode";
import type { GridReveal } from "./GridReveal";
import type { GridSheetTab } from "./GridSheetTab";
import type { GridStats } from "./GridStats";

/**
 * Everything the Grid chrome shows.
 */
export type GridState = { 
/**
 * Sheet tabs.
 */
sheets: Array<GridSheetTab>, 
/**
 * The active sheet.
 */
active_sheet: number, 
/**
 * The name box (`G10`, `A1:C3`, `3R x 2C` while selecting, a defined name).
 */
name_box: string, 
/**
 * The formula bar's content for the active cell (its formula, or its value as typed).
 */
formula: string, 
/**
 * The mode.
 */
mode: GridMode, 
/**
 * The editor, while editing.
 */
editor: GridEditor | null, 
/**
 * The active cell's format.
 */
format: GridCellFormat, 
/**
 * Pane layout.
 */
layout: GridLayout, 
/**
 * Gridlines shown.
 */
gridlines: boolean, 
/**
 * Headings shown.
 */
headings: boolean, 
/**
 * Formulas shown instead of results.
 */
show_formulas: boolean, 
/**
 * The last scroll request.
 */
reveal: GridReveal | null, 
/**
 * Copy or Cut marked a range (Esc clears it).
 */
copy_marked: boolean, 
/**
 * The selection is several cells.
 */
multi: boolean, 
/**
 * The selection is one or more whole rows.
 */
whole_rows: boolean, 
/**
 * The selection is one or more whole columns.
 */
whole_columns: boolean, 
/**
 * Statistics of a multi-cell selection.
 */
stats: GridStats | null, 
/**
 * Defined names the name box lists.
 */
names: Array<string>, 
/**
 * The selected chart: its drawing number, rectangle (sheet pixels) and state for the Chart
 * Design and Format tabs and the Format pane.
 */
drawing: GridDrawing | null, };
